{
  "name": "opencode-devin-bridge",
  "version": "2.0.0-beta.0",
  "description": "OpenCode bridge for Devin models",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sudokar/opencode-devin-bridge.git"
  },
  "homepage": "https://github.com/sudokar/opencode-devin-bridge#readme",
  "bugs": {
    "url": "https://github.com/sudokar/opencode-devin-bridge/issues"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "bin": {
    "opencode-devin-bridge": "./dist/src/cli.js"
  },
  "files": [
    "dist"
  ],
  "packageManager": "bun@1.2.14",
  "scripts": {
    "build": "bun run tsc -p tsconfig.build.json",
    "typecheck": "bun run tsc --noEmit",
    "test": "bun test",
    "test:unit": "bun test tests/unit",
    "test:request": "bun run tests/live/request.ts",
    "test:analyze": "bun run tests/live/analyze.ts",
    "clean": "rm -rf dist"
  },
  "keywords": [
    "opencode",
    "devin",
    "bridge",
    "ai",
    "plugin",
    "authentication"
  ],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "@opencode/plugin": "^2.2.5",
    "xdg-basedir": "^5.1.0"
  },
  "devDependencies": {
    "@types/bun": "^1.4.2",
    "@types/node": "^25.0.8",
    "typescript": "^7.0.2"
  },
  "peerDependencies": {
    "typescript": "^5"
  },
  "engines": {
    "node": ">=18.0.0",
    "bun": ">=1.0.0"
  }
}
